  validateState(state);
  if (!event || typeof event !== 'object' || Array.isArray(event) ||
      typeof event.type !== 'string') {
    throw new TypeError('invalid event');
  }

  let page = state.page;
  let pageCount = state.pageCount;

  if (event.type === 'next') {
    if (pageCount > 0) page = (page + 1) % pageCount;
  } else if (event.type === 'previous') {
    if (pageCount > 0) page = (page - 1) % pageCount;
  } else if (event.type === 'jump') {
    if (!Number.isSafeInteger(event.page)) throw new TypeError('invalid page');
    if (event.page < 0 || event.page >= pageCount) throw new RangeError('page out of range');
    page = event.page;
  } else if (event.type === 'resize') {
    if (!Number.isSafeInteger(event.pageCount) || event.pageCount < 0) {
      throw new TypeError('invalid page count');
    }
    pageCount = event.pageCount;
    page = pageCount === 0 ? 0 : Math.min(page, pageCount - 1);
  } else {
    throw new TypeError('unknown event type');
  }

  const changed = page !== state.page || pageCount !== state.pageCount;
  if (changed && state.revision === Number.MAX_SAFE_INTEGER) {
    throw new RangeError('revision overflow');
  }
  return {
    page,
    pageCount,
    revision: changed ? state.revision + 1 : state.revision
  };
