'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api).sort(), ['reducePager']);
const { reducePager } = api;

function transition(state, event, expected) {
  const stateBefore = { ...state };
  const eventBefore = { ...event };
  const result = reducePager(state, event);
  assert.deepEqual(result, expected);
  assert.deepEqual(state, stateBefore);
  assert.deepEqual(event, eventBefore);
  assert.notStrictEqual(result, state);
}

transition({ page: 0, pageCount: 3, revision: 4 }, { type: 'next' },
  { page: 1, pageCount: 3, revision: 5 });
transition({ page: 2, pageCount: 3, revision: 4 }, { type: 'next' },
  { page: 0, pageCount: 3, revision: 5 });
transition({ page: 0, pageCount: 3, revision: 4 }, { type: 'previous' },
  { page: 2, pageCount: 3, revision: 5 });
transition({ page: 0, pageCount: 0, revision: 4 }, { type: 'next' },
  { page: 0, pageCount: 0, revision: 4 });
transition({ page: 0, pageCount: 0, revision: 4 }, { type: 'previous' },
  { page: 0, pageCount: 0, revision: 4 });
transition({ page: 1, pageCount: 3, revision: 4 }, { type: 'jump', page: 1 },
  { page: 1, pageCount: 3, revision: 4 });
transition({ page: 1, pageCount: 3, revision: 4 }, { type: 'jump', page: 2 },
  { page: 2, pageCount: 3, revision: 5 });
transition({ page: 1, pageCount: 3, revision: 4 }, { type: 'resize', pageCount: 5 },
  { page: 1, pageCount: 5, revision: 5 });
transition({ page: 3, pageCount: 5, revision: 4 }, { type: 'resize', pageCount: 2 },
  { page: 1, pageCount: 2, revision: 5 });
transition({ page: 2, pageCount: 3, revision: 4 }, { type: 'resize', pageCount: 0 },
  { page: 0, pageCount: 0, revision: 5 });
transition({ page: 1, pageCount: 3, revision: 4 }, { type: 'resize', pageCount: 3 },
  { page: 1, pageCount: 3, revision: 4 });

for (const state of [
  null, [], {},
  { page: -1, pageCount: 1, revision: 0 },
  { page: 0.5, pageCount: 1, revision: 0 },
  { page: 0, pageCount: '1', revision: 0 },
  { page: 0, pageCount: 1, revision: NaN },
  { page: 0, pageCount: 1, revision: Number.MAX_SAFE_INTEGER + 1 }
]) assert.throws(() => reducePager(state, { type: 'next' }), TypeError);

assert.throws(() => reducePager({ page: 1, pageCount: 0, revision: 0 }, { type: 'next' }), RangeError);
assert.throws(() => reducePager({ page: 2, pageCount: 2, revision: 0 }, { type: 'next' }), RangeError);

const validState = { page: 0, pageCount: 2, revision: 0 };
for (const event of [null, [], {}, { type: 'wat' }, { type: 1 },
  { type: 'jump', page: '1' }, { type: 'jump', page: 1.2 },
  { type: 'resize', pageCount: -1 }, { type: 'resize', pageCount: Infinity }]) {
  assert.throws(() => reducePager(validState, event), TypeError);
}
assert.throws(() => reducePager(validState, { type: 'jump', page: 2 }), RangeError);
assert.throws(() => reducePager({ page: 0, pageCount: 0, revision: 0 }, { type: 'jump', page: 0 }), RangeError);
assert.throws(() => reducePager(
  { page: 0, pageCount: 2, revision: Number.MAX_SAFE_INTEGER },
  { type: 'next' }
), RangeError);
assert.deepEqual(reducePager(
  { page: 0, pageCount: 0, revision: Number.MAX_SAFE_INTEGER },
  { type: 'next' }
), { page: 0, pageCount: 0, revision: Number.MAX_SAFE_INTEGER });

